diff --git a/flutter_app/lib/sandbox/wasm_shell.dart b/flutter_app/lib/sandbox/wasm_shell.dart
index 3f7f0ff1b..0b3f132e2 100644
--- a/flutter_app/lib/sandbox/wasm_shell.dart
+++ b/flutter_app/lib/sandbox/wasm_shell.dart
@@ -81,7 +81,9 @@ final class WasiSandboxShell implements Shell, BackgroundShell, GitShellHost {
     this.sandboxHostPath,
