    this.lua,
    this.workingDirectory,
    this.sandboxHostPath,
    http.Client? httpClient,
    this.moduleLoader,
    Map<String, WasmModule>? lazyModuleCache,
  }) : _httpClient = httpClient ?? http.Client(),
       _lazyModules = lazyModuleCache ?? <String, WasmModule>{},
