      sed: await loadAsset('sed.wasm'),
      awk: await loadAsset('awk.wasm'),
      tar: await loadAsset('tar.wasm'),
      gzip: await loadAsset('gzip.wasm'),
      zip: await loadAsset('zip.wasm'),
      workingDirectory: workingDirectory,
